    def query_files(self):
        sel_keywords = self.combo.currentData()

        #
        # Replace trailing "," with ) for SQL Query syntax
        #
        replace_loc = len(sel_keywords) - 11 + 1
        keywords_sql = sel_keywords[:replace_loc - 1] + ")"
        print(keywords_sql)

        dbname = self.lineEditDb.text()
        tablename = self.lineEditTable.text()
        mydb = mc.connect(
            #
            # host connection is ip-reprotect-tools IP address
            #
            host="10.0.98.52",
            user="pycharmrob",
            password="IPRepr0tection",
            database=dbname
        )

        mycursor = mydb.cursor()
        # Query is a combination of search based on MOUNT_PATH OR keywords
        # sql_query="SELECT * FROM scanresults WHERE MOUNT_PATH LIKE %s""
        # searchsql="%" + self.lineEditSearch.text() + "%"

        # print(searchsql)


        # Return nothing if no keywords selected
        if not sel_keywords:
            return  # or set sql_query to return empty results

        # Build query knowing keywords exist
        sql_query = "SELECT * FROM scanresults WHERE "
        conditions = [f"MATCHED_KEYWORDS IN {keywords_sql}"]

        if self.lineEditSearch.text():
            conditions.append(f"MOUNT_PATH LIKE '%{self.lineEditSearch.text()}%'")

        sql_query += " AND ".join(conditions)

        print(sql_query)

        mycursor.execute(sql_query)

        print("Rows returned = ", mycursor.rowcount)

        result = mycursor.fetchall()

        try:
            self.tableWidget.setRowCount(0)
            self.tableWidget.setColumnCount(len(result[0]))

            # Get column names
            column_names = [i[0] for i in mycursor.description]
            self.tableWidget.setHorizontalHeaderLabels(column_names)

            for row_number, row_data in enumerate(result):
                print(row_number)
                self.tableWidget.insertRow(row_number)
                for column_number, data in enumerate(row_data):
                    # print(column_number)
                    self.tableWidget.setItem(row_number, column_number,
                                            QTableWidgetItem(str(data)))
                    self.tableWidget.item(row_number, column_number).setFlags(
                        QtCore.Qt.ItemIsEnabled | QtCore.Qt.ItemIsSelectable)

        except mc.Error as e:
            print('Error')

        mycursor.close()
        mydb.close()

